def residual_operations(
    operations: Operations | TransformedOperations | Sequence[Mapping[str, Any]],
    basis: ArrayLike,
    *,
    tolerance: Optional[float] = None,
) -> Operations | TransformedOperations:
    """The operations of a list that keep the metric of a cell: W with WᵀGW = G, G the metric tensor
    of ``basis`` (columns a, b). It is the point symmetry of a distorted lattice among the
    operations of a group, e.g. those of p4mm that a rectangular cell keeps. The operations are read
    by ``matrix``, the integer matrix W on lattice coordinates, as ``operations`` gives them; the
    list is taken as it is, not closed into a group, and the kept operations are the ones of the
    list, in its order. The deviation counts relative to the largest entry of G (``tolerance``,
    default ``EPSILON``), so the result does not depend on the unit of the edge lengths. Raises
    SymcrysError for an operation without a 2 × 2 integer matrix and for a basis that is not a
    non-singular 2 × 2 matrix.

    Parameters
    ----------
    tolerance : keyword-only, optional
        Two numbers closer than this count as equal; default ``EPSILON`` (10⁻⁵). It is measured per
        matrix entry for operations, as the distance of unit vectors for directions and per
        coordinate modulo the lattice for points (docs/conventions.md, "Tolerances").

    Returns
    -------
    Operations
        The kept operations of the caller, in their order.
    """
    given = _shared.operation_list(operations, ("matrix",))
    kept = _call(
        "residualOperations",
        [{**op, "index": i} for i, op in enumerate(given)],
        _shared.array(basis, "basis", np.float64),
        _shared.options(tolerance=tolerance),
    )
    ops = operations if isinstance(operations, (Operations, TransformedOperations)) else _shared.operations_of(given, Operations)
    result: Operations | TransformedOperations = _shared.select(ops, kept)
    return result


def change_of_coordinates(
    linear_part: ArrayLike,
    *,
    origin_shift: Optional[ArrayLike] = None,
    points: Optional[ArrayLike] = None,
    directions: Optional[ArrayLike] = None,
    planes: Optional[ArrayLike] = None,
    metric: Optional[ArrayLike] = None,
    operations: Optional[Operations | TransformedOperations | Sequence[Mapping[str, Any]]] = None,
    tolerance: Optional[float] = None,
) -> CoordinateChange:
    """Changes the coordinate system of the plane by the pair (P, p), with 2 × 2 matrices: the new
    basis is (a′, b′) = (a, b)·P and the new origin lies at p. Transforms the given quantities by
    ITA's equations: point coordinates x′ = P⁻¹(x − p), vector coefficients [uv]′ = P⁻¹[uv], Miller
    indices (hk)′ = (hk)P, the metric tensor G′ = PᵀGP, and operations W′ = P⁻¹WP, w′ = P⁻¹(w + (W −
    I)p); and gives the inverse pair (Q, q) = (P⁻¹, −P⁻¹p). det P may be negative.

    P and the matrices W are read each number as a fraction and transformed exactly, so that every
    result, the inverse pair included, can be passed back: a number that is a fraction to rounding
    is that fraction, another is read as the simplest fraction within the tolerance (default
    ``EPSILON``; 0.3333333 is 1/3). The origin shift p and the translations w are positions: a
    fraction to rounding (1/3 as 0.3333333333) is that fraction, another number is taken as it is
    (0.1234 stays 0.1234). P is rational in a change between lattice bases, as in ITA: an entry of P
    that needs a fraction with a denominator above tolerance^(−1/3) (46 at 10⁻⁵) is refused
    (docs/conventions.md, "Tolerances"). A transformed operation has a ``matrix`` and a
    ``translation``. Raises SymcrysError for a singular P, an entry of P that is not rational within
    the tolerance, a quantity of the wrong shape, an unknown quantity, an operation with det W ≠ ±1,
    and one whose W′ is not integral.

    Parameters
    ----------
    linear_part
        P, the linear part: its columns are the new basis vectors a′, b′ in the old basis; det P ≠
        0, also negative.
    origin_shift : keyword-only, optional
        p, the origin shift: the coordinates of the new origin in the old coordinate system; default
        zero.
    points : keyword-only, optional
        Point coordinates x: x′ = P⁻¹(x − p).
    directions : keyword-only, optional
        Coefficients [uv] of vectors, e.g. directions: [uv]′ = P⁻¹[uv]; not changed by the origin
        shift.
    planes : keyword-only, optional
        Miller indices (hk) of lines: (hk)′ = (hk)P; not changed by the origin shift.
    metric : keyword-only, optional
        The metric tensor G: G′ = PᵀGP.
    operations : keyword-only, optional
        Operations (W, w): W′ = P⁻¹WP, w′ = P⁻¹(w + (W − I)p).
    tolerance : keyword-only, optional
        Two numbers closer than this count as equal; default ``EPSILON`` (10⁻⁵). It is measured per
        matrix entry for operations, as the distance of unit vectors for directions and per
        coordinate modulo the lattice for points (docs/conventions.md, "Tolerances").
    """
    result: CoordinateChange = _shared.convert(
        _call(
            "changeOfCoordinates",
            _shared.options(linear_part=linear_part, origin_shift=origin_shift),
            _shared.options(
                points=points,
                directions=directions,
                planes=planes,
                metric=metric,
                operations=None if operations is None else _shared.operation_list(operations, ("matrix",)),
            ),
            _shared.options(tolerance=tolerance),
        ),
        _S_CoordinateChange,
    )
    return result
